using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using WebApi.Contracts.Alerts;
using WebApi.Infrastructure.Persistence.Entities;
using WebApi.Integration.Tests.Support;
using Xunit;
using WebApi.Contracts.Common;
using WebApi.Infrastructure.Settings;
using WebApi.Infrastructure.Notifications;
namespace WebApi.Integration.Tests;
public sealed class NotificationCompatibilityBridgeTests
{
    private const string Nine="""{"smtpHost":"mail.example.test","smtpPort":587,"fromEmail":"sender@example.test","smtpSecretRef":"vault://fixture/mail","webhookUrl":"https://hook.example.test/notify","webhookSecretRef":"vault://fixture/hook","smtpEnabled":true,"webhookEnabled":true,"smtpSecurity":"StartTlsRequired"}""";
    private static async Task<ApiFixture> Setup(bool readOnly=true){var f=new ApiFixture();await f.InitializeAsync(b=>b.Configuration["CompatibilityNotifications:Mode"]=readOnly?"ReadOnly":"Disabled");await f.SeedScopeAsync(platformAdmin:true);await SystemSettingsFixture.PromoteAsync(f);await ObservationTestSupport.GrantAsync(f,["alert.rule.manage"]);(await f.LoginAsync()).EnsureSuccessStatusCode();return f;}
    private static async Task Seed(ApiFixture f,string value){await using var db=f.Context();db.Add(new SystemSetting{Key="system.notification",Value=value,UpdatedBy=f.User.Id});await db.SaveChangesAsync();}
    private static SaveAlertRuleRequest Definition(ApiFixture f)=>new(f.Organization.Id,f.Project.Id,f.Environment.Id,"Recovery bridge","request_rps","request_rps > 999999999","Warning",true,0,"Environment",null,60,new(true,["Webhook"]));
    [Fact]public async Task ExactNineReadsSixWithoutRewritingStoredJson(){await using var f=await Setup();await Seed(f,Nine);string storedBefore;await using(var before=f.Context())storedBefore=(await before.Set<SystemSetting>().SingleAsync()).Value;using var response=await f.Client.GetAsync("/api/v1/settings/system/notification");response.EnsureSuccessStatusCode();var value=(await response.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("values");Assert.Equal(6,value.EnumerateObject().Count());Assert.Equal("mail.example.test",value.GetProperty("smtpHost").GetString());Assert.DoesNotContain("vault://",value.GetRawText());await using var db=f.Context();Assert.Equal(storedBefore,(await db.Set<SystemSetting>().SingleAsync()).Value);Assert.Equal(1,(await db.Set<SystemSetting>().SingleAsync()).Revision);}
    [Fact]public async Task LegacySixStillReadsWithoutRewriting(){await using var f=await Setup();var fields=JsonSerializer.Deserialize<Dictionary<string,JsonElement>>(Nine)!;foreach(var name in new[]{"smtpEnabled","webhookEnabled","smtpSecurity"})fields.Remove(name);var six=JsonSerializer.Serialize(fields);await Seed(f,six);string storedBefore;await using(var before=f.Context())storedBefore=(await before.Set<SystemSetting>().SingleAsync()).Value;(await f.Client.GetAsync("/api/v1/settings/system/notification")).EnsureSuccessStatusCode();await using var db=f.Context();Assert.Equal(storedBefore,(await db.Set<SystemSetting>().SingleAsync()).Value);}
    [Fact]public void DuplicateExtendedPropertyFailsClosed(){var invalid=Nine.Replace("\"smtpEnabled\":true", "\"smtpEnabled\":true,\"smtpEnabled\":false");var error=Assert.Throws<ApiException>(()=>SettingsValueCodec.Decode("notification",invalid,CompatibilityNotificationMode.ReadOnly));Assert.Equal(503,error.Status);}
    [Fact]public async Task DisabledCompatibilityStillRejectsNine(){await using var f=await Setup(false);await Seed(f,Nine);Assert.Equal(HttpStatusCode.ServiceUnavailable,(await f.Client.GetAsync("/api/v1/settings/system/notification")).StatusCode);}
    [Theory][InlineData("smtpEnabled","false")][InlineData("smtpEnabled",null)][InlineData("webhookEnabled",123)][InlineData("smtpSecurity","Optional")][InlineData("extra",true)]
    public async Task UnknownOrInvalidExtensionsFailClosed(string key,object? value){await using var f=await Setup();var fields=JsonSerializer.Deserialize<Dictionary<string,JsonElement>>(Nine)!;fields[key]=JsonSerializer.SerializeToElement(value);await Seed(f,JsonSerializer.Serialize(fields));Assert.Equal(HttpStatusCode.ServiceUnavailable,(await f.Client.GetAsync("/api/v1/settings/system/notification")).StatusCode);}
    [Fact]public async Task PartialExtendedJsonFailsClosed(){await using var f=await Setup();var fields=JsonSerializer.Deserialize<Dictionary<string,JsonElement>>(Nine)!;fields.Remove("webhookEnabled");await Seed(f,JsonSerializer.Serialize(fields));Assert.Equal(HttpStatusCode.ServiceUnavailable,(await f.Client.GetAsync("/api/v1/settings/system/notification")).StatusCode);}
    [Fact]public async Task NotificationSaveCannotOverwriteNine(){await using var f=await Setup();await Seed(f,Nine);using var response=await SystemSettingsFixture.SendAsync(f,HttpMethod.Put,"notification","",new{values=new{smtpHost=(string?)null,smtpPort=(int?)null,fromEmail=(string?)null,smtpSecretRef=new{operation="Clear"},webhookUrl=(string?)null,webhookSecretRef=new{operation="Clear"}},confirmationToken="unused"},"\"1\"");Assert.Equal((HttpStatusCode)423,response.StatusCode);Assert.Equal("notification_maintenance_mode",(await response.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("code").GetString());await using var db=f.Context();Assert.Equal(9,JsonDocument.Parse((await db.Set<SystemSetting>().SingleAsync()).Value).RootElement.EnumerateObject().Count());}
    [Fact]public async Task RuleCreateCannotWriteDuringRecovery(){await using var f=await Setup();using var response=await f.WriteAsync(HttpMethod.Post,"/api/v1/observability/alert-rules",Definition(f));Assert.Equal((HttpStatusCode)423,response.StatusCode);await using var db=f.Context();Assert.Empty(await db.Set<AlertRule>().ToArrayAsync());}
    [Theory][InlineData("update")][InlineData("enable")][InlineData("disable")]
    public async Task ExistingRuleMutationsAreReadOnly(string operation){await using var f=await Setup();var rule=new AlertRule{OrganizationId=f.Organization.Id,ProjectId=f.Project.Id,EnvironmentId=f.Environment.Id,Name="Frozen",NormalizedName="FROZEN",Metric="request_rps",Expression="request_rps > 999999999",TargetType="Environment",Severity="Warning",Enabled=true,WindowSeconds=60,ForSeconds=0,Notification="{\"inConsole\":true,\"requestedChannels\":[\"Webhook\"],\"externalEnabled\":true}",CreatedBy=f.User.Id,UpdatedBy=f.User.Id};await using(var db=f.Context()){db.Add(rule);await db.SaveChangesAsync();}using var response=await f.WriteAsync(operation=="update"?HttpMethod.Put:HttpMethod.Post,"/api/v1/observability/alert-rules/"+rule.Id+(operation=="update"?"":"/"+operation),operation=="update"?Definition(f):null,"\"1\"");Assert.Equal((HttpStatusCode)423,response.StatusCode);await using var verify=f.Context();var after=await verify.Set<AlertRule>().SingleAsync();Assert.True(after.Enabled);Assert.Equal(1,after.Revision);Assert.Contains("externalEnabled",after.Notification);}
    [Theory][InlineData("/api/v1/settings/system/notification/tests")][InlineData("/api/v1/notification-deliveries/00000000-0000-0000-0000-000000000001/retry")]
    public async Task NewNotificationMutationRoutesRejectDuringRecovery(string route){await using var f=await Setup();using var response=await f.WriteAsync(HttpMethod.Post,route,new{channel="Email",email="recipient@example.test"},"\"1\"");Assert.Equal((HttpStatusCode)423,response.StatusCode);}
    [Fact]public async Task OtherSettingsAndBusinessWritesStillWork(){await using var f=await Setup();using var saved=await SystemSettingsFixture.SaveAsync(f,"gateway",new{defaultRouteTimeoutMs=12000,maxRequestBodyMb=20,configRefreshIntervalSeconds=2});saved.EnsureSuccessStatusCode();using var project=await f.WriteAsync(HttpMethod.Post,"/api/v1/organizations/"+f.Organization.Id+"/projects",new{code="AFTERBRIDGE",name="Created after bridge"});project.EnsureSuccessStatusCode();}
}
